document.addEventListener("DOMContentLoaded",function (){const sections = document.querySelectorAll(".content-section");const tocLinks = document.querySelectorAll(".toc-link");const progressBar = document.getElementById("reading-progress");const progressLabel = document.getElementById("reading-percentage");const mobileTocToggle = document.getElementById("mobile-toc-toggle");const mobileToc = document.getElementById("mobile-toc");const printBtn = document.getElementById("print-docs");const shareBtn = document.getElementById("share-docs");const bookmarkBtn = document.getElementById("bookmark-docs");function updateActiveTocLink(){let currentSection = "";sections.forEach((section) =>{const sectionTop = section.offsetTop;if (window.pageYOffset >= sectionTop - 150){currentSection = section.getAttribute("id");}});tocLinks.forEach((link) =>{link.classList.remove("active");if (link.getAttribute("href") === `#${currentSection}`){link.classList.add("active");}});}function updateReadingProgress(){if (!progressBar || !progressLabel) return;const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;const scrollHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;const pct = Math.min(100,Math.round((scrollTop / scrollHeight) * 100));progressBar.style.width = pct + "%";progressLabel.textContent = pct + "%";}window.addEventListener("scroll",() =>{updateActiveTocLink();updateReadingProgress();});updateActiveTocLink();updateReadingProgress();tocLinks.forEach((link) =>{link.addEventListener("click",function (e){e.preventDefault();const targetId = this.getAttribute("href");const targetElement = document.querySelector(targetId);if (targetElement){window.scrollTo({top:targetElement.offsetTop - 20,behavior:"smooth",});history.pushState(null,null,targetId);}});});if (mobileTocToggle && mobileToc){mobileTocToggle.addEventListener("click",() =>{const expanded = mobileTocToggle.getAttribute("aria-expanded") === "true";mobileTocToggle.setAttribute("aria-expanded",String(!expanded));mobileToc.classList.toggle("hidden",expanded);});}if (printBtn){printBtn.addEventListener("click",() => window.print());}if (shareBtn){shareBtn.addEventListener("click",async () =>{const shareData ={title:document.title,url:location.href};try{if (navigator.share){await navigator.share(shareData);}else{await navigator.clipboard.writeText(location.href);Helpers.showToast("Link copied to clipboard","success");}}catch (err){Helpers.showToast("Unable to share","error");}});}if (bookmarkBtn){bookmarkBtn.addEventListener("click",() =>{try{localStorage.setItem("docsBookmarked",location.href);Helpers.showToast("Documentation bookmarked","success");}catch (e){Helpers.showToast("Bookmark failed","error");}});}});